def _is_missing(value):
    """True if a stat/type value from the DB is effectively empty (None,
    NaN, or a stringified 'none')."""
    if value is None:
        return True
    if isinstance(value, float) and value != value:  # NaN != NaN
        return True
    if isinstance(value, str) and value.strip().lower() in ("", "none", "nan"):
        return True
    return False


def handle_raid_counters(ui, pokedex, on_pokemon_click=None):

    # Get the value from the LineEdit and strip Pokedex number if present
    raid_boss = ui.raid_pokemon.text().strip()
    # Remove the Pokedex number format " (#480)" if it exists
    if " (#" in raid_boss:
        raid_boss = raid_boss.split(" (#")[0]
    ui.raid_pokemon.clear()

    print("User entered: ", raid_boss)

    counters = pokedex.get_raid_counters(raid_boss)

    if counters is None:
        set_background(ui, "poke_background.jpg", pokemon_type=None)
        ui.raid_pokemon_header.setText("Raid Boss Not Found")
        ui.raid_pokemon_header.setStyleSheet(
            f"background-color: {DEFAULT_TYPE_COLOR};"
            "color: white;"
            "font-weight: bold;"
            "font-size: 11pt;"
            "border-radius: 14px;"
            "padding: 2px;"
        )
        ui.card.setStyleSheet(
            "QFrame#card {"
            "background-color: rgba(255, 255, 255, 235);"
            f"border: 5px solid {DEFAULT_TYPE_COLOR};"
            "border-radius: 22px;"
            "}"
        )
        ui.search_box.setStyleSheet(
            "QFrame#search_box {"
            f"background-color: {DEFAULT_TYPE_COLOR};"
            "border-radius: 12px;"
            "}"
        )
        for i in range(1, 6):
            getattr(ui, f"pokemon{i}").setText(f"{i}. --")
            getattr(ui, f"sprite{i}").setIcon(QtGui.QIcon())
        return

    print(counters)

    # Get the actual Pokemon name (in case user entered a number)
    boss_data = None
    boss_display_name = raid_boss.title()

    # Try to parse as a number first
    try:
        boss_num = int(raid_boss)
        result = pokedex.get_pokemon_by_number(boss_num)
        if result is not None and not result.empty:
            boss_data = result.iloc[0].to_dict()
            boss_display_name = str(boss_data['pokemon']).title()
    except (ValueError, TypeError):
        # If not a number, try by name
        boss_data = pokedex.get_pokemon_by_name(raid_boss)
        if boss_data is not None:
            boss_display_name = str(boss_data.get('pokemon', raid_boss)).title()

    # Theme the card/background off the raid boss's own type (the
    # counters themselves are Pokemon strong *against* that type)
    boss_type = None
    if boss_data is not None and not _is_missing(boss_data.get('type_1')):
        boss_type = str(boss_data['type_1']).lower()

    color = TYPE_COLORS.get(boss_type, DEFAULT_TYPE_COLOR)
    name_of_background = f"{boss_type}.jpg" if boss_type else "poke_background.jpg"
    set_background(ui, name_of_background, pokemon_type=boss_type)

    # Include Pokedex number if available
    header_text = f"Counters for {boss_display_name}"
    if boss_data is not None and 'pokedex_no' in boss_data:
        pokedex_no = boss_data['pokedex_no']
        header_text = f"Counters for {boss_display_name} (#{pokedex_no})"
    ui.raid_pokemon_header.setText(header_text)
    ui.raid_pokemon_header.setStyleSheet(
        f"background-color: {color};"
        "color: white;"
        "font-weight: bold;"
        "font-size: 11pt;"
        "border-radius: 14px;"
        "padding: 2px;"
    )
    ui.card.setStyleSheet(
        "QFrame#card {"
        "background-color: rgba(255, 255, 255, 235);"
        f"border: 5px solid {color};"
        "border-radius: 22px;"
        "}"
    )
    ui.search_box.setStyleSheet(
        "QFrame#search_box {"
        f"background-color: {color};"
        "border-radius: 12px;"
        "}"
    )

    # Results, ranked 1-5, each with its sprite. get_raid_counters() can
    # return fewer than 5 rows (if fewer than 5 Pokemon match the
    # weakness criteria), so only fill in what we actually got and clear
    # out any remaining rows from a previous search.
    names = counters["pokemon"].tolist()
    for i in range(5):
        rank = i + 1
        pokemon_btn = getattr(ui, f"pokemon{rank}")
        sprite_btn = getattr(ui, f"sprite{rank}")
        type_badge = getattr(ui, f"type{rank}")

        if i >= len(names):
            pokemon_btn.setText(f"{rank}. --")
            sprite_btn.setIcon(QtGui.QIcon())
            type_badge.clear()
            continue

        name = str(names[i])
        pokemon_btn.setText(f"{rank}. {name.title()}")

        detail = pokedex.get_pokemon_by_name(name)
        sprite_data = detail.get("sprite") if detail is not None else None

        if sprite_data:
            pixmap = QtGui.QPixmap()
            pixmap.loadFromData(sprite_data)
            pixmap = pixmap.scaled(
                56,
                56,
                QtCore.Qt.KeepAspectRatio,
                QtCore.Qt.SmoothTransformation
            )
            icon = QtGui.QIcon(pixmap)
            sprite_btn.setIcon(icon)
            sprite_btn.setIconSize(QtCore.QSize(56, 56))
        else:
            sprite_btn.setIcon(QtGui.QIcon())

        # Set up click handlers
        try:
            pokemon_btn.clicked.disconnect()
            sprite_btn.clicked.disconnect()
        except TypeError:
            pass

        if on_pokemon_click:
            pokemon_btn.clicked.connect(lambda checked, pname=name: on_pokemon_click(pname))
            sprite_btn.clicked.connect(lambda checked, pname=name: on_pokemon_click(pname))
        else:
            pokemon_btn.clicked.connect(lambda checked, pname=name, pui=ui, pdb=pokedex: _lookup_pokemon_raid(pui, pdb, pname))
            sprite_btn.clicked.connect(lambda checked, pname=name, pui=ui, pdb=pokedex: _lookup_pokemon_raid(pui, pdb, pname))

        # Display type badges
        if detail is not None:
            type_1 = detail.get('type_1')
            type_2 = detail.get('type_2')
            type_badge = getattr(ui, f"type{rank}")
            type_badge2 = getattr(ui, f"type{rank}_2")

            if type_1 and not _is_missing(type_1):
                type_color = TYPE_COLORS.get(str(type_1).lower(), DEFAULT_TYPE_COLOR)
                type_badge.setText(str(type_1).capitalize())
                type_badge.setStyleSheet(
                    f"font-size: 8pt; font-weight: bold; border-radius: 4px; padding: 2px; "
                    f"background-color: {type_color}; color: white;"
                )

            if type_2 and not _is_missing(type_2):
                import pandas as pd
                if pd.notna(type_2):
                    type_color2 = TYPE_COLORS.get(str(type_2).lower(), DEFAULT_TYPE_COLOR)
                    type_badge2.setText(str(type_2).capitalize())
                    type_badge2.setStyleSheet(
                        f"font-size: 8pt; font-weight: bold; border-radius: 4px; padding: 2px; "
                        f"background-color: {type_color2}; color: white;"
                    )
                    type_badge2.show()
                else:
                    type_badge2.hide()
            else:
                type_badge2.hide()


def _lookup_pokemon_raid(ui, pokedex, pokemon_name):
    """Look up a pokemon from raid counters click and display it in lookup window."""
    import look_up

    poke_data = pokedex.get_pokemon_by_name(pokemon_name)
    if poke_data is None:
        return

    # Use the lookup function to display the pokemon
    look_up._lookup_pokemon_by_name(ui, pokedex, pokemon_name)


